{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket lacks encryption",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption enabled. This can lead to sensitive data being stored unencrypted, increasing the risk of data exposure."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"changeme_aws_s3_bucket_backend_simple\" {\n  force_destroy = true\n  bucket        = \"changeme-${random_id.changeme_backends_s3_bucket_name.hex}\"\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm = \"AES256\"\n      }\n    }\n  }\n}",
  "fix_summary": "Added server-side encryption configuration to the S3 bucket to ensure data is encrypted at rest using AES256."
}
